# The motif used when none fits, or the model named one not listed.
FALLBACK = "collection"

_BY_NAME: dict[str, str] = dict(MOTIFS)


def motif(name: str) -> str | None:
    """The inner markup of a motif, or None for a name not vendored here."""
    return _BY_NAME.get(name)


def resolve(raw: str) -> str | None:
    """The motif a model meant, when it did not use a name from the list
    verbatim: an icon-font spelling (`bi-tree-fill`), a plural, or a plain word
    for the subject (`leaf`, `space`). A cheap model often answers that way,
    and dropping its choice to the collection glyph throws away the one thing
    that makes a cover look like its subject. None when nothing is close."""
    name = raw.strip().lower().replace(" ", "-").replace("_", "-")
    name = name.removeprefix("bi-").removesuffix("-fill")
    for n in (name, name.rstrip("s")):
        if n in _BY_NAME:
            return n
    for words, m in ALIASES:
        if name in words.split(","):
            return m if m in _BY_NAME else None
    return None


